        col=grid[r][c]
        if (r,c) in seen: continue
        seen.add((r,c)); q=[(r,c)]; pts=[]
        while q:
          x,y=q.pop(); pts.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
              seen.add((a,b)); q.append((a,b))
        comps.append((col,pts))
    return comps

