      r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
      S=set(pts); H=r1-r0+1; W=c1-c0+1
      if not any(r in (0,h-1) or c in (0,w-1) for r,c in pts): continue
      for sc in (c0,c1):
        if any((r,sc) not in S for r in range(r0,r1+1)): continue
        for endrow in (r0,r1):
          for t in range(1,H+1):
